<script setup>
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {cashManagementService} from './service'
import BaseButton from '../../components/ui/BaseButton.vue'
import BaseInput from '../../components/ui/BaseInput.vue'
const route=useRoute(),rows=ref([]),loading=ref(false),error=ref(''),search=ref(''),action=ref(''),active=ref(null),form=ref({})
const section=computed(()=>route.meta.cashManagementSection||'vaults'),title=computed(()=>({vaults:'Vaults',transfers:'Transfers','opening-balances':'Opening Balances',reconciliations:'Reconciliations'}[section.value]))
const paths={vaults:'/cash-management/vaults',transfers:'/cash-management/transfers','opening-balances':'/cash-management/opening-balances',reconciliations:'/cash-management/reconciliations'}
const shown=computed(()=>rows.value.filter(r=>!search.value||Object.values(r).some(v=>String(v??'').toLowerCase().includes(search.value.toLowerCase()))))
const cols=computed(()=>{let k=section.value==='vaults'?['vault_code','vault_name','vault_type','status','id']:section.value==='transfers'?['transfer_code','source_vault_id','dest_vault_id','initiated_amount','status','id']:section.value==='opening-balances'?['vault_id','currency_id','opening_balance','status','id']:['vault_id','currency_id','business_date','counted_physical_amount','status','id'];return k.filter(x=>rows.value.some(r=>x in r)).slice(0,5)})
const defs=computed(()=>section.value==='vaults'?[['vault_type','Vault type'],['vault_code','Vault code'],['vault_name','Vault name'],['owner_user_id','Owner ID'],['custodian_user_id','Custodian ID']]:section.value==='transfers'?[['source_vault_id','Source vault ID'],['dest_vault_id','Destination vault ID'],['currency_id','Currency ID'],['transfer_type','Transfer type'],['initiated_amount','Amount'],['tolerance_amount','Tolerance'],['remarks','Remarks']]:section.value==='opening-balances'?[['vault_id','Vault ID'],['currency_id','Currency ID'],['opening_balance','Opening balance'],['notes','Notes']]:[['vault_id','Vault ID'],['currency_id','Currency ID'],['business_date','Business date'],['counted_physical_amount','Counted amount'],['notes','Notes']])
async function load(){loading.value=true;error.value='';try{let r=await cashManagementService.list(paths[section.value]);rows.value=Array.isArray(r)?r:Array.isArray(r?.data)?r.data:Array.isArray(r?.data?.items)?r.data.items:Array.isArray(r?.items)?r.items:[]}catch(e){error.value=e?.message||'Could not load records';rows.value=[]}finally{loading.value=false}}
function rid(r){return r?.id||r?.uuid||r?.transfer_id||r?.opening_balance_id||r?.reconciliation_id}
function open(m,r){action.value=m;active.value=r||null;form.value=r?{...r}:{vault_type:'TELLER_TILL',vault_code:'TL-001',vault_name:'Teller 001 Till',owner_user_id:25,custodian_user_id:12,source_vault_id:'a1b2c3d4-1111-4222-8333-123456789001',dest_vault_id:'a1b2c3d4-1111-4222-8333-123456789002',currency_id:'d1b2c3d4-1111-4222-8333-123456789001',transfer_type:'VAULT_TO_TELLER',initiated_amount:10000,tolerance_amount:10,remarks:'Daily teller cash allocation',opening_balance:25000,notes:'Initial teller cash handover',business_date:'2026-11-23',counted_physical_amount:22450}}
async function save(){loading.value=true;try{if(action.value==='edit')await cashManagementService.patch(paths[section.value]+'/'+encodeURIComponent(rid(active.value)),form.value);else await cashManagementService.post(paths[section.value],form.value);action.value='';await load()}catch(e){error.value=e?.message||'Save failed'}finally{loading.value=false}}
async function operate(t,r){let id=encodeURIComponent(rid(r)),p='',b={};if(t==='receive'){p='/cash-management/transfers/'+id+'/receive';b={received_amount:r.initiated_amount||10000,receipt_notes:'Cash counted and matched with transfer slip'}}else if(t==='accept')p='/cash-management/opening-balances/'+id+'/accept';else if(t==='reject'){p='/cash-management/opening-balances/'+id+'/reject';b={reason:'Received amount does not match the handover slip'}}else p='/cash-management/reconciliations/'+id+'/approve';loading.value=true;error.value='';try{await cashManagementService.post(p,b);await load()}catch(e){error.value=e?.message||'Action failed'}finally{loading.value=false}}
watch(section,()=>{action.value='';load()});onMounted(load)
</script>
<template><section class="module-page"><div class="module-page-intro"><div><h2>{{title}}</h2><p class="module-description">List records first, then add, edit or process them.</p></div><BaseButton class="module-primary-btn" @click="open('add')">＋ Add Record</BaseButton></div><div class="module-stat-row"><div class="module-stat-card"><span>Total records</span><strong>{{rows.length}}</strong></div><div class="module-stat-card"><span>Filtered</span><strong>{{shown.length}}</strong></div><div class="module-stat-card"><span>Section</span><strong>Cash Management</strong></div></div><section class="module-panel"><div class="module-panel-header"><h3>{{title}} register</h3><label class="module-search"><BaseInput v-model="search" placeholder="Search records..." size="sm"/></label><BaseButton variant="secondary" size="sm" @click="load">Refresh</BaseButton></div><p v-if="error" class="cash-error">{{error}}</p><div class="module-table-wrap"><table class="module-table"><thead><tr><th v-for="c in cols" :key="c">{{c.replaceAll('_',' ')}}</th><th>Actions</th></tr></thead><tbody><tr v-if="loading"><td :colspan="cols.length+1" class="module-empty-state">Loading…</td></tr><tr v-else-if="!shown.length"><td :colspan="cols.length+1" class="module-empty-state">No records found.</td></tr><tr v-for="r in shown" :key="rid(r)"><td v-for="c in cols" :key="c">{{r[c]??'—'}}</td><td><div class="cash-actions"><BaseButton variant="secondary" size="sm" @click="open('view',r)">View</BaseButton><BaseButton variant="secondary" size="sm" @click="open('edit',r)">Edit</BaseButton><BaseButton v-if="section==='transfers'" variant="secondary" size="sm" @click="operate('receive',r)">Receive</BaseButton><BaseButton v-if="section==='opening-balances'" variant="secondary" size="sm" @click="operate('accept',r)">Accept</BaseButton><BaseButton v-if="section==='opening-balances'" variant="danger" size="sm" @click="operate('reject',r)">Reject</BaseButton><BaseButton v-if="section==='reconciliations'" variant="secondary" size="sm" @click="operate('approve',r)">Approve</BaseButton></div></td></tr></tbody></table></div><div class="module-table-footer">Showing {{shown.length}} of {{rows.length}}</div></section><section v-if="action" class="module-panel"><div class="module-panel-header"><h3>{{action==='view'?'View record':action==='edit'?'Edit record':'Add record'}}</h3><BaseButton variant="secondary" size="sm" @click="action=''">Close</BaseButton></div><form class="cash-form" @submit.prevent="save"><div v-for="([key,label]) in defs" :key="key" class="cash-field"><label>{{label}}</label><input v-model="form[key]" :disabled="action==='view'" :type="['owner_user_id','custodian_user_id','initiated_amount','tolerance_amount','opening_balance','counted_physical_amount'].includes(key)?'number':key==='business_date'?'date':'text'"/></div><div class="cash-submit"><BaseButton v-if="action!=='view'" type="submit" :disabled="loading">{{loading?'Saving…':'Save'}}</BaseButton></div></form></section></section></template>
<style scoped>.cash-actions{display:flex;gap:6px;flex-wrap:wrap;white-space:nowrap}.cash-form{padding:20px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.cash-field{display:flex;flex-direction:column;gap:6px}.cash-field input{padding:9px;border:1px solid var(--border-color,#dbe2ea);border-radius:7px}.cash-submit{grid-column:1/-1;display:flex;justify-content:flex-end}.cash-error{color:#b42332;padding:10px 20px}@media(max-width:650px){.cash-form{grid-template-columns:1fr}}</style>